/// 这个字符在 `WIDE_CP` 里的下标。
fn wide_idx(ch: char) -> Option<usize> {
    WIDE_CP.binary_search(&(ch as u32)).ok()
}

/// 一段文本占多少格（按字符宽度累加，不含行尾补齐）。
pub fn cells_of(s: &str) -> u64 {
    s.chars().map(char_cells).sum()
}

/// 这个字符占几格。**非 ASCII 一律 2 格**：覆盖集里是汉字与全角符号，
/// 在中文语境下都按双宽排；ASCII 一列一格。
pub fn char_cells(ch: char) -> u64 {
    if (ch as u32) < 0x80 {
        1
    } else {
        2
    }
}

/// 宽字符的**缺失字形**：空心框（边框 + 中间一横）。
/// 它必须与"空格"和"`?`"都不同——前者会把缺失伪装成空、后者会伪装成 ASCII 内容。
fn tofu(bits: &mut [u32; 32]) {
    for (r, row) in bits.iter_mut().enumerate() {
        *row = if r == 0 || r == 31 || r == 15 { 0xFFFF_FFFF } else { 0x8000_0001 };
    }
}

/// 顶部这一行是**标签栏**（不是标题栏）：一个标签页 + 一个 `+`，右侧是窗口按钮。
/// 标签页只有一个（今天只有一个会话），但布局按"N 个标签 + 是否溢出"写成规则。
pub const TITLE_ROWS: u64 = 1;
/// 标签上的标题。
pub const TAB_LABEL: &str = "Aurora shell";
/// 标签条底色：**比正文亮**（截图取样 #333333）。与正文相反方向的对比让活动页
/// 看起来是"从条上挖下去"的一块——Windows 11 / Windows Terminal 的现行样式。
/// #58 pass B：**层次对齐参考图**——条底是整条最暗的一档，活动标签比它亮一档。
/// 参考实测：条底 `#0A0A0A` / 活动标签 `#2E2E2E` / 面板 `#2C2C2C`；在我们的灰阶上取
/// `#1F1F1F` 与 `#2E2E2E`（正文仍是 `#0C0C0C`，所以活动标签与正文之间有一道可见的边界）。
const TITLE_BG: u32 = 0x00_33_33_33;
/// 活动标签顶角那两个像素的过渡色（截图里是 #2B2B2B 一带）。
const TITLE_BG_HI: u32 = 0x00_2B_2B_2B;
/// 活动标签的底色 **= 正文底色**（"挖掉"效果）。
/// 活动标签的底色（比条底亮一档——这是参考图的层次方向，与旧版"挖到正文色"相反）。
const TAB_ACTIVE_BG: u32 = 0x00_2E_2E_2E;
/// 标签文字：活动页亮、非活动页暗（截图取样 #E1E1E1 / #9A9A9A）。
const TAB_TEXT: u32 = 0x00_E1_E1_E1;
const TAB_DIM: u32 = 0x00_9A_9A_9A;
/// 标签上那个 `>_` 图标的颜色（PowerShell 图标的浅蓝）。
const TAB_ICON: u32 = 0x00_A0_BB_E0;
/// 指针停在非活动标签上时的底色：比条底亮一点点，**不抢活动页**。
const TAB_HOVER_BG: u32 = 0x00_3A_3A_3A;
/// 参考图里条底是 `#333333`（不是近黑），标签文字近白、非活动页浅灰。
const TAB_INK: u32 = 0x00_F2_F2_F2;
const TAB_INK_DIM: u32 = 0x00_D8_D8_D8;
/// 非活动标签的 `>_` 图标：同色降一档（不活动页的图标位不再留空）。
const TAB_ICON_DIM: u32 = 0x00_6E_7C_90;

/// 标签栏的几何。**绘制与命中测试共用这一份**——两处各算一遍，点击就会落在画的地方旁边。
// ---------------------------------------------------------------- #58：`∨` 下拉
/// 面板宽（格）与最多行数；背景比条底亮一档、悬停再亮一档（参考图的面板是 `#2C2C2C`）。
pub const MENU_W: u64 = 30;
pub const MENU_MAX_ROWS: u64 = 6;
pub const MENU_BG: u32 = 0x00_2C_2C_2C;
pub const MENU_BG_HOVER: u32 = 0x00_3A_3A_3A;
pub const MENU_EDGE: u32 = 0x00_4A_4A_4A;

/// 面板里的一行：左标签、右提示、是否置灰（置灰 = 今天没有动作，点了要在串口如实报）。
#[derive(Clone, Copy)]
pub struct MenuRow {
    pub label: &'static str,
    pub hint: &'static str,
    pub dim: bool,
}

/// 面板几何（格）：**从 `∨` 那一格往下开**（不是贴屏幕右边——用户实测：
/// 面板要是从别处冒出来，读起来不像"这个箭头拉下来的"）。右边界越界就整体左移，
/// 但左边界仍在 `∨` 附近。**绘制与命中都从这里取**，两处各算一遍就会分家。
/// 面板行高（像素）：与 1× 的 16 px 格子解耦，保持参考图的 32 px 行。
pub const MENU_ROW_H: u64 = 32;
/// 面板底部留白（参考图最后一行下面还有一点空）。
pub const MENU_PAD_B: u64 = 4;
/// 面板与标签条之间的缝隙（贴死会与活动标签的圆角连成一片）。
pub const MENU_GAP: u64 = 4;
/// 面板内容四周的内边距（选项与面板边之间留出来），以及 hover 条的左右缩进。
pub const MENU_PAD_T: u64 = 4;
pub const MENU_PAD_X: u64 = 6;

pub fn menu_rect(cols: u64, tabs: u64, n_rows: u64) -> (u64, u64, u64) {
    let rows = n_rows.min(MENU_MAX_ROWS);
    let lay = BarLayout::of(cols);
    let shown = tabs.min(lay.fit);
    // 面板锚点压在 `∨` **右侧**：`+`/`∨` 现在按像素画（宽 12/12、间隔 10），
    // 占满 base..base+56 这 7 格；+5 会让面板盖住 `∨`（实测看不到箭头）。
    let x = lay.plus_col(shown) + 7;
    let x = if x + MENU_W > cols { cols.saturating_sub(MENU_W) } else { x };
    (x.max(1), BAR_H + MENU_GAP, rows)
}

/// 点在一个面板行上？返回行号。y 是**像素**（面板从 `BAR_H` 起、每行 32 px）。
pub fn menu_hit(cols: u64, tabs: u64, n_rows: u64, x_px: u64, y_px: u64) -> Option<u8> {
    let (mx, y0, rows) = menu_rect(cols, tabs, n_rows);
    let cx = x_px / CELL_W;
    let top = y0 + MENU_PAD_T;
    if cx < mx || cx >= mx + MENU_W || y_px < top || y_px >= top + rows * MENU_ROW_H {
        return None;
    }
    Some(((y_px - top) / MENU_ROW_H) as u8)
}

/// #58 pass A：窗口按钮的宽度（格）与字形边长（像素）。**所有绘制与命中都从这里取**。
/// 8×8 四分之一圆的一像素覆盖率（×15）：离线算好，画标签圆角时与条底混合。
/// **不能用浮点**（`check-nofloat`）：内核里只查这张表。
const CORNER_AA: [[u8; 8]; 8] = [
    [ 0,  0,  0,  0,  3,  9, 13, 15],
    [ 0,  0,  0,  9, 15, 15, 15, 15],
    [ 0,  0, 11, 15, 15, 15, 15, 15],
    [ 0,  9, 15, 15, 15, 15, 15, 15],
    [ 3, 15, 15, 15, 15, 15, 15, 15],
    [ 9, 15, 15, 15, 15, 15, 15, 15],
    [13, 15, 15, 15, 15, 15, 15, 15],
    [15, 15, 15, 15, 15, 15, 15, 15],
];

/// 面板 5px 圆角、hover 条 4px 圆角（比标签顶部的 8px 小一档）。
const CORNER_AA5: [[u8; 5]; 5] = [
    [ 0,  0,  5, 11, 15],
    [ 0,  8, 15, 15, 15],
    [ 5, 15, 15, 15, 15],
    [11, 15, 15, 15, 15],
    [15, 15, 15, 15, 15],
];
const CORNER_AA4: [[u8; 4]; 4] = [
    [ 0,  3, 10, 14],
    [ 3, 14, 15, 15],
    [10, 15, 15, 15],
    [14, 15, 15, 15],
];

pub const BTN_W: u64 = 6;
pub const GLYPH: u64 = 12;

pub struct BarLayout {
    pub strip_l: u64,
    pub strip_r: u64,
    pub tab_w: u64,
    pub fit: u64,
}

impl BarLayout {
    pub fn of(cols: u64) -> Self {
        // 标签条用**半号字**之后，"12 个字符"只占 96px；参考图的标签是窄条
        // （图标 + 文字 + 关闭 + 内边距），不是旧版 17 格的宽条。12 格 = 192px：
        // 图标 16 + 间距 6 + 文字 96 + 间距 8 + 关闭 16 + 右边距 ≈ 150，仍有余量。
        const TAB_CELLS: u64 = 30; // 30 × 8 px = 240 px，参考图的活动标签宽度
        let _ = TAB_LABEL;
        let tab_w = TAB_CELLS;
        let strip_l = 1;
        // 右侧三个按钮**贴右边缘**各占一格（截图里最后那个 × 就在窗口右边界上）；
        // 原来留了 5 格边距，按钮看起来像散落在条中间。
        // #58 pass A：三个窗口按钮**每枚 2 格**（32 px，贴近参考图 ~40 px 的命中区）。
        let strip_r = cols.saturating_sub(3 * BTN_W);
        let fit = if strip_r > strip_l + tab_w {
            (strip_r - strip_l) / tab_w
        } else {
            0
        };
        Self { strip_l, strip_r, tab_w, fit }
    }
    /// 标签**紧挨着**排（参考图里两个标签之间没有整格的缝；旧版留了一格=16px，
    /// 活动页右边看着空出一大截）。
    pub fn tab_col(&self, i: u64) -> u64 {
        self.strip_l + i * self.tab_w
    }
    /// 第 i 个窗口按钮的起始列（i = 0/1/2 = `-`/`□`/`×`）。
    pub fn btn_col(&self, i: u64) -> u64 {
        self.strip_r + i * BTN_W
    }
    /// 字形盒在 2 格宽里居中时左上角的 x 偏移（像素）。
    pub fn glyph_x(&self) -> u64 {
        (BTN_W * CELL_W - GLYPH) / 2
    }
    /// `+` 在哪一列
    pub fn plus_col(&self, shown: u64) -> u64 {
        self.strip_l + shown * self.tab_w
    }
}

/// 窗口的三态（S6q 补记二）。**这不是窗口管理器**：没有宿主窗口可挪，
/// 所以"最小化/最大化"落在**终端自己的版面**上，行为写死在这里：
/// - `Normal`：标签栏 + 正文 + 输入行（默认）；
/// - `Minimized`：只留标签栏，正文整块刷成底色（再点一次 `-` 或点任一标签恢复）；
/// - `Maximized`：收起标签栏，正文从第 0 行开始（多一行），三个窗口按钮仍画在右上角三格。
///
/// **为什么不做"真的放大窗口"**：guest 改不了 QEMU 的窗口尺寸（没有 virtio-gpu 的那种接口），
/// 假装能改就是硬约束⑦说的夸大。这里只动**我们画得出来的那一块**。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Chrome {
    Normal,
    Minimized,
    Maximized,
    /// S6r：浮窗正文——没有标签栏、也没有全局按钮（窗口自己的标题栏由调用方画）。
    Floating,
}

impl Chrome {
    /// 画不画标签栏
    pub fn tabs(self) -> bool {
        !matches!(self, Chrome::Maximized | Chrome::Floating)
    }
    /// 画不画正文（正文区 + 尾行）
    pub fn body(self) -> bool {
        !matches!(self, Chrome::Minimized)
    }
    /// 画不画右上角那三个**全局**按钮（浮窗有自己的标题栏按钮）。
    pub fn buttons(self) -> bool {
        matches!(self, Chrome::Normal | Chrome::Maximized)
    }
}

/// 点在了哪儿。只有 `Body` 是"终端正文"，其余都是标签栏上的控件。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Hit {
    TabClose(u8),
    Tab(u8),
    NewTab,
    Layout,
    Min,
    Max,
    Close,
    Bar,
    Body,
}

impl Hit {
    pub fn name(self) -> &'static str {
        match self {
            Hit::TabClose(_) => "标签关闭",
            Hit::Tab(0) => "标签0",
            Hit::Tab(1) => "标签1",
            Hit::Tab(_) => "标签N",
            Hit::NewTab => "新建标签",
            Hit::Layout => "版面切换",
            Hit::Min => "最小化",
            Hit::Max => "最大化",
            Hit::Close => "关闭窗口",
            Hit::Bar => "标签栏空白",
            Hit::Body => "终端正文",
        }
    }
}

/// 浮动窗口的矩形（**格**为单位，S6r）。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct WinRect {
    pub x: u64,
    pub y: u64,
    pub cols: u64,
    pub rows: u64,
}

impl WinRect {
    /// 正文矩形（去掉标题栏那一行）。`rows <= TITLE_ROWS` 时没有正文。
    pub fn body(&self) -> Option<WinRect> {
        if self.rows <= TITLE_ROWS {
            return None;
        }
        Some(WinRect { x: self.x, y: self.y + TITLE_ROWS, cols: self.cols, rows: self.rows - TITLE_ROWS })
    }

    /// 两个矩形是否有交（格为单位）。重画一扇窗之后，压在它上面的窗**都要补一遍**——
    /// 这就是"只重画矩形"能成立的前提：遮挡关系由 z 序 + 这份交判定显式处理。
    pub fn intersects(&self, o: &WinRect) -> bool {
        self.x < o.x + o.cols && o.x < self.x + self.cols
            && self.y < o.y + o.rows && o.y < self.y + self.rows
    }
}

/// 点在窗口的哪一处（S6r）。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WinHit {
    Title,
    Min,
    Max,
    Close,
    Body,
    None,
}

/// 像素坐标 → 某个窗口内的命中项。最右三格是 `-`/`□`/`×`（与标题栏绘制同一份几何）。
pub fn win_hit(w: WinRect, x_px: u64, y_px: u64) -> WinHit {
    let cx = x_px / CELL_W;
    let cy = y_px.saturating_sub(BAR_H + BODY_PAD) / CELL_H;
    if cx < w.x || cx >= w.x + w.cols || cy < w.y || cy >= w.y + w.rows {
        return WinHit::None;
    }
    if cy >= w.y + TITLE_ROWS {
        return WinHit::Body;
    }
    // #58 pass A：标题栏右端三枚按钮各占 **2 格**（与 `win_buttons`/`paint_title` 同一几何）。
    let rel = cx - w.x;
    let back = w.cols.saturating_sub(rel);
    if back <= BTN_W {
        WinHit::Close
    } else if back <= 2 * BTN_W {
        WinHit::Max
    } else if back <= 3 * BTN_W {
        WinHit::Min
    } else {
        WinHit::Title
    }
}

/// 屏幕像素坐标 → 命中项。第 0 行是标签栏，其余全是正文。
pub fn hit_test(
    cols: u64,
    tabs: u64,
    x_px: u64,
    y_px: u64,
    ch: Chrome,
    active: u64,
    hover: Option<u8>,
) -> Hit {
    let c = x_px / CELL_W;
    let lay = BarLayout::of(cols);
    if !ch.tabs() {
        // 最大化：右上角三格仍是三个按钮（标签栏没了，按钮不能跟着消失——
        // 否则 maximize 就变成单向门，没有恢复的办法）。其余全算正文。
        if y_px < BAR_H {
            if c >= lay.btn_col(0) && c < lay.btn_col(1) {
                return Hit::Min;
            }
            if c >= lay.btn_col(1) && c < lay.btn_col(2) {
                return Hit::Max;
            }
            if c >= lay.btn_col(2) {
                return Hit::Close;
            }
        }
        return Hit::Body;
    }
    if y_px >= BAR_H {
        return Hit::Body;
    }
    let shown = tabs.min(lay.fit);
    for i in 0..shown {
        let c0 = lay.tab_col(i);
        if c >= c0 && c < c0 + lay.tab_w {
            // #58：条目右上角**只保留 `×`**，而且只在"它是活动标签"或"指针停在它上面"时**可点**
            // （画与命中同一条规则——否则看不见的 × 也能点，正是要防的误关）。
            let rel = c - c0;
            let x_visible = i as u64 == active || hover == Some(i as u8);
            // `×` 画在 `tab_end-19`、宽 9px，横跨最后**三格**的前两格（rel=tab_w-3..tab_w-2）。
            // 命中必须与画同源：旧口径 rel+2 只认后两格，画出来的左半 ×（rel=tab_w-3）点不动，
            // 用户要点好几下才碰巧点中右半（实测"关闭点多次才关闭"）。改 rel+3 覆盖整个画的 ×。
            return if rel + 3 >= lay.tab_w && x_visible {
                Hit::TabClose(i as u8)
            } else {
                Hit::Tab(i as u8)
            };
        }
    }
    // S6t：`+` 的列要用**实际画出去的那个 shown**，不是写死的 1——两个标签都在时
    // `plus_col(1)` 落在第二个标签自己的范围里，被上面那个循环先吃掉，`+` 就点不动了。
    // `+` 占 base..base+26（约三格），`∨` 占 base+26..base+56（约四格）。
    if c >= lay.plus_col(shown) && c <= lay.plus_col(shown) + 3 {
        return Hit::NewTab;
    }
    if c > lay.plus_col(shown) + 3 && c <= lay.plus_col(shown) + 7 {
        return Hit::Layout;
    }
    if c >= lay.btn_col(0) && c < lay.btn_col(1) {
        return Hit::Min;
    }
    if c >= lay.btn_col(1) && c < lay.btn_col(2) {
        return Hit::Max;
    }
    if c >= lay.btn_col(2) {
        return Hit::Close;
    }
    Hit::Bar
}

/// 配色取 Windows Terminal 的默认：近黑底（#0C0C0C）+ 浅灰字（#CCCCCC）。
/// 纯黑/纯白看着"生"、对比也过强；这一对与测试图案的三条带仍然都不同 ⇒
/// "画在带上的字"和"带本身"照样分得开（§240 那条对账不受影响）。
pub const FG: u32 = 0x00_CC_CC_CC;
pub const BG: u32 = 0x00_0C_0C_0C;

impl Term {
    /// 按帧缓冲的几何开一块终端。几何小到放不下一个字符时返回 `None`
    /// （不"缩着画"：那会让 `cols` 与夹具算的不一样，红因会变成对账而不是容量）。
    pub fn new(f: &Frame) -> Option<Term> {
        let (w, h, _) = f.geom();
        if w < CELL_W * 8 || h < CELL_H * (BAND_ROWS + 2) {
            return None;
        }
        let rows = (h - BAR_H - BODY_PAD) / CELL_H;
        Some(Self { cols: (w - BODY_LEFT) / CELL_W, rows, ox: BODY_LEFT, oy: BAR_H + BODY_PAD })
    }

    /// 在屏幕的 `(x_cells, y_cells)` 处开一个 `cols × rows` 的**视口**（S6r）。
    /// 越界的像素由 [`Term::put`] 静默裁掉——那是窗口的边界，不是错误。
    pub fn at(f: &Frame, x_cells: u64, y_cells: u64, cols: u64, rows: u64) -> Option<Term> {
        let (w, h, _) = f.geom();
        if cols < 8 || rows == 0
            || x_cells * CELL_W + cols * CELL_W > w
            || BAR_H + BODY_PAD + y_cells * CELL_H + rows * CELL_H > h
            || BODY_LEFT + x_cells * CELL_W + cols * CELL_W > w
        {
            return None;
        }
        Some(Self { cols, rows, ox: BODY_LEFT + x_cells * CELL_W, oy: BAR_H + BODY_PAD + y_cells * CELL_H })
    }

    /// 视口原点（像素）。窗口的标题栏/边框按这个画，调用方不再自己乘一遍格子。
    pub fn origin(&self) -> (u64, u64) {
        (self.ox, self.oy)
    }

    /// 落笔：坐标是**视口内**的，加原点后写到帧缓冲；视口外的像素**静默跳过**。
    /// 返回 false 只表示"这一笔真写失败了"（映射坏了），不表示"被裁掉了"。
    #[inline]
    fn put(&self, f: &Frame, x: u64, y: u64, color: u32) -> bool {
        if x >= self.cols * CELL_W || y >= self.rows * CELL_H {
            return true;
        }
        f.put(self.ox + x, self.oy + y, color).is_ok()
    }

    /// 清掉"标签条与正文之间的那条留白"（`BAR_H .. BAR_H+BODY_PAD`）。
    /// 这一段既不属于条、也不属于正文行——面板/浮窗收掉时它的旧像素没人负责，
    /// 实测会在条下面留一条 1px 的残线。
    /// 把一块矩形刷成正文底色（面板收起时先把整个面板矩形清掉，再按列段重画正文）。
    /// **整块清**是为了兜住那些"不在正文行网格里"的东西：指针保存/恢复的旧底、
    /// 悬停行的抗锯齿边、圆角——只按行/列刷会漏（实测残留一块 6×8 的旧底色）。
    pub fn clear_rect(&self, f: &Frame, x0: u64, y0: u64, w: u64, h: u64) {
        self.rect_abs(f, x0, y0, w, h, BG);
    }

    pub fn clear_gap(&self, f: &Frame) {
        self.rect_abs(f, 0, BAR_H, self.cols * CELL_W, BODY_PAD, BG);
    }

    pub fn dims(&self) -> (u64, u64) {
        (self.cols, self.rows)
    }

    /// 正文区能放几行（冻结带不算）。实时重画用它来定窗口，不在调用方写死分辨率。
    pub fn body_rows(&self) -> usize {
        (self.rows - BAND_ROWS) as usize
    }

    pub fn frozen() -> bool {
        FROZEN.load(Ordering::Acquire)
    }

    /// 把一行位图按 [`SCALE`] 放大成块写出去：`SCALE=2` 时一个字形像素是 2×2 个硬件像素。
    /// 返回 false 表示有点写失败（几何是启动信息给的，越界说明上面哪一步算错了，不能吞）。
    fn blit(&self, f: &Frame, x0: u64, y: u64, bits: u32, width_px: usize) -> bool {
        for c in 0..width_px {
            let on = bits & (1 << (width_px - 1 - c)) != 0;
            let color = if on { FG } else { BG };
            for dy in 0..SCALE {
                for dx in 0..SCALE {
                    if !self.put(f, x0 + c as u64 * SCALE + dx, y + dy, color) {
                        return false;
                    }
                }
            }
        }
        true
    }

    /// 画一个字符（宽字符占 2 格）。冻结之后是 no-op（返回 false 表示"没画"，调用方可以据此数账）。
    pub fn put_char(&self, f: &Frame, col: u64, row: u64, ch: char) -> bool {
        if Self::frozen() || row >= self.rows || col + char_cells(ch) > self.cols {
            return false;
        }
        // 1× 格子：正文也用界面那份 8×16 / 16×16 灰阶字（与标签条同源），按正文底色混合。
        // **先铺格底**：`ch_ink` 只写墨迹，不铺底——空格/重画就擦不掉旧像素（实测：
        // 下拉面板关掉后仍留在屏上、看起来像界面卡住）。
        let w = char_cells(ch) * CELL_W;
        self.rect(f, col * CELL_W, row * CELL_H, w, CELL_H, BG);
        self.ch_ink(f, col * CELL_W, row * CELL_H, ch, FG);
        true
    }

    /// 擦掉光标：把它画过的三行半格宽原样刷回背景。
    ///
    /// **为什么一条"擦"就够了**：光标画在 `cells_of(文本)` 那一格，也就是正文结尾的**空格**上；
    /// 只有整行写满（列被夹到最后一格）时那一格才有字——那种情况下擦掉的会是字尾三点，
    /// 下一次整窗重画会补回来（判据比的是文本，不是这三点）。
    pub fn caret_erase(&self, f: &Frame, col: u64, row: u64) {
        if row >= self.rows || col >= self.cols {
            return;
        }
        let x0 = col * CELL_W;
        let y0 = row * CELL_H;
        for yy in (CELL_H - 3)..CELL_H {
            for x in 0..(CELL_W / 2) {
                if !self.put(f, x0 + x, y0 + yy, BG) {
                    return;
                }
            }
        }
    }

    /// 画光标：格底三行、半格宽的下划线（像终端里的块状光标，但不会盖住字）。
    pub fn caret(&self, f: &Frame, col: u64, row: u64) {
        if Self::frozen() || row >= self.rows || col >= self.cols {
            return;
        }
        let x0 = col * CELL_W;
        let y0 = row * CELL_H;
        for yy in (CELL_H - 3)..CELL_H {
            for x in 0..(CELL_W / 2) {
                if !self.put(f, x0 + x, y0 + yy, FG) {
                    return;
                }
            }
        }
    }

    /// 画一个**浮动窗口的标题栏**（S6r）：视口应为 `cols × 1` 格的那一行。
    /// 底色分聚焦/不聚焦两档；左起 `>_` 图标，文字从第 3 格起，最右三格 `-`/`□`/`×`。
    pub fn paint_title(&self, f: &Frame, title: &str, focused: bool) {
        let w = self.cols * CELL_W;
        // 不聚焦的标题栏也要**看得出来是一条标题栏**（用正文色就整条隐形了，第一版实测）。
        let bg = if focused { TAB_ACTIVE_BG } else { 0x00_24_24_24 };
        self.rect(f, 0, 0, w, CELL_H, bg);
        let ink = if focused { TAB_TEXT } else { TAB_DIM };
        for k in 0..5u64 {
            let _ = self.put(f, 10 + k, 9 + k, TAB_ICON);
            let _ = self.put(f, 10 + k, 17 - k, TAB_ICON);
        }
        self.rect(f, 18, 19, 6, 2, TAB_ICON);
        let mut c = 3u64;
        for ch in title.chars() {
            let cw = char_cells(ch);
            if c + cw + 3 > self.cols {
                break;
            }
            self.ch_ink(f, c * CELL_W, 0, ch, ink);
            c += cw;
        }
        // #58 pass A：与标签条同一份几何（2 格宽、12 px 字形、2 px 笔画）。
        let lay = BarLayout::of(self.cols);
        let gx = |i: u64| lay.btn_col(i) * CELL_W + lay.glyph_x();
        let y0 = (BAR_H - GLYPH) / 2;
        let (w, t) = (GLYPH, 2u64);
        self.rect(f, gx(0), y0 + GLYPH / 2 - 1, w, t, ink);
        self.rect(f, gx(1), y0, w, t, ink);
        self.rect(f, gx(1), y0 + GLYPH - t, w, t, ink);
        self.rect(f, gx(1), y0, t, GLYPH, ink);
        self.rect(f, gx(1) + w - t, y0, t, GLYPH, ink);
        self.cross(f, gx(2), y0, GLYPH, ink);
    }

    /// 只写位图里**亮**的像素（背景透明）。标题栏用它把文字叠在自铺的底色上。
    fn ink(&self, f: &Frame, x0: u64, y0: u64, bits: u32, width_px: usize) -> bool {
        for c in 0..width_px {
            if bits & (1 << (width_px - 1 - c)) == 0 {
                continue;
            }
            for dy in 0..SCALE {
                for dx in 0..SCALE {
                    if !self.put(f, x0 + c as u64 * SCALE + dx, y0 + dy, FG) {
                        return false;
                    }
                }
            }
        }
        true
    }

    /// 画一条实心矩形（屏幕像素坐标）。
    /// 四角圆角的面板。`corner = 5` 用面板表、`4` 用 hover 表；半径写死成两档，
    /// 是为了不把二维表做成动态索引（内核里表都是常量）。
    fn rounded_rect_abs(&self, f: &Frame, x0: u64, y0: u64, w: u64, h: u64,
                        inside: u32, outside: u32, corner: u64) {
        let (r, table): (u64, fn(u64, u64) -> u32) = if corner == 4 {
            (4, |dy, dx| CORNER_AA4[dy as usize][dx as usize] as u32)
        } else {
            (5, |dy, dx| CORNER_AA5[dy as usize][dx as usize] as u32)
        };
        self.rect_abs(f, x0 + r, y0, w - 2 * r, h, inside);
        self.rect_abs(f, x0, y0 + r, r, h - 2 * r, inside);
        self.rect_abs(f, x0 + w - r, y0 + r, r, h - 2 * r, inside);
        for dy in 0..r {
            for dx in 0..r {
                let c = mix(inside, outside, table(dy, dx));
                let _ = self.put_abs(f, x0 + dx, y0 + dy, c);
                let _ = self.put_abs(f, x0 + w - 1 - dx, y0 + dy, c);
                let _ = self.put_abs(f, x0 + dx, y0 + h - 1 - dy, c);
                let _ = self.put_abs(f, x0 + w - 1 - dx, y0 + h - 1 - dy, c);
            }
        }
    }

    /// **绝对屏幕坐标**（不加减视口原点）：标签条/面板/窗口按钮用这一套——
    /// 正文的视口从 `BAR_H` 起，条本身必须画在屏幕顶。
    fn put_abs(&self, f: &Frame, x: u64, y: u64, color: u32) -> bool {
        f.put(x, y, color).is_ok()
    }

    fn rect_abs(&self, f: &Frame, x0: u64, y0: u64, w: u64, h: u64, color: u32) {
        for y in y0..y0 + h {
            for x in x0..x0 + w {
                if !self.put_abs(f, x, y, color) {
                    return;
                }
            }
        }
    }

    fn cross_abs(&self, f: &Frame, x0: u64, y0: u64, size: u64, color: u32) {
        for i in 0..size {
            for t in 0..2u64 {
                let _ = self.put_abs(f, x0 + i, y0 + i + t, color);
                let _ = self.put_abs(f, x0 + size - 1 - i, y0 + i + t, color);
            }
        }
    }

    /// 顶部圆角的填充：角区 8×8 用覆盖率表混合，下面与中间是纯色。
    fn rounded_top_abs(&self, f: &Frame, x0: u64, y0: u64, w: u64, h: u64, inside: u32, outside: u32) {
        const R: u64 = 8;
        self.rect_abs(f, x0, y0 + R, w, h - R, inside);
        for dy in 0..R {
            self.rect_abs(f, x0 + R, y0 + dy, w - 2 * R, 1, inside);
            for dx in 0..R {
                let a = CORNER_AA[dy as usize][dx as usize] as u32;
                let c = mix(inside, outside, a);
                let _ = self.put_abs(f, x0 + dx, y0 + dy, c);
                let _ = self.put_abs(f, x0 + w - 1 - dx, y0 + dy, c);
            }
        }
    }

    fn ch_ink_ui_abs(&self, f: &Frame, x0: u64, y0: u64, ch: char, fg: u32, bg: u32) {
        let k = ch as u32;
        if k < 0x80 {
            if !(0x20..=0x7E).contains(&k) {
                return;
            }
            let g = FONT_UI[(k - 0x20) as usize];
            for r in 0..16u64 {
                let row = g[r as usize] as u32;
                for c in 0..8u64 {
                    let a = (row >> (28 - 4 * c)) & 0xF;
                    if a != 0 && !self.put_abs(f, x0 + c, y0 + r, mix(fg, bg, a)) {
                        return;
                    }
                }
            }
        } else if let Ok(i) = WIDE_UI_CP.binary_search(&k) {
            let g = FONT_UI_WIDE[i];
            for r in 0..16u64 {
                let row = g[r as usize];
                for c in 0..16u64 {
                    let a = ((row >> (60 - 4 * c)) & 0xF) as u32;
                    if a != 0 && !self.put_abs(f, x0 + c, y0 + r, mix(fg, bg, a)) {
                        return;
                    }
                }
            }
        }
    }

    fn rect(&self, f: &Frame, x0: u64, y0: u64, w: u64, h: u64, color: u32) {
        for y in y0..y0 + h {
            for x in x0..x0 + w {
                if !self.put(f, x, y, color) {
                    return;
                }
            }
        }
    }

    /// 画一个字符的亮像素（可指定颜色）。表外字符什么都不画。
    /// 正文落字：1× 格子（8×16）下正文与界面同字号，用同一份 8×16/16×16 灰阶资产，
    /// 按正文底色（BG）混合。
    fn ch_ink(&self, f: &Frame, x0: u64, y0: u64, ch: char, color: u32) {
        // 19 px 的行里 16 px 的字形垂直居中（+2）。
        let y0 = y0 + (CELL_H - 16) / 2;
        let k = ch as u32;
        if k < 0x80 {
            if !(0x20..=0x7E).contains(&k) {
                return;
            }
            let g = FONT_BODY[(k - 0x20) as usize];
            for r in 0..16u64 {
                let row = g[r as usize] as u32;
                for c in 0..8u64 {
                    let a = (row >> (28 - 4 * c)) & 0xF;
                    if a != 0 && !self.put(f, x0 + c, y0 + r, mix(color, BG, a)) {
                        return;
                    }
                }
            }
        } else if let Ok(i) = WIDE_BODY_CP.binary_search(&k) {
            let g = FONT_BODY_WIDE[i];
            for r in 0..16u64 {
                let row = g[r as usize];
                for c in 0..16u64 {
                    let a = ((row >> (60 - 4 * c)) & 0xF) as u32;
                    if a != 0 && !self.put(f, x0 + c, y0 + r, mix(color, BG, a)) {
                        return;
                    }
                }
            }
        }
    }

    /// **界面字号**字形：一份独立的 8×16（ASCII）/ 16×16（宽字）位图资产。
    /// 为什么不再用"隔行隔列抽样"：抽样会把 22px 字形的笔画抽断（用户实测"模糊"）。
    /// 只给标签条与下拉面板；正文一律 `ch_ink`（16×32）。
    fn ch_ink_ui(&self, f: &Frame, x0: u64, y0: u64, ch: char, fg: u32, bg: u32) {
        let k = ch as u32;
        if k < 0x80 {
            if !(0x20..=0x7E).contains(&k) {
                return;
            }
            let g = FONT_UI[(k - 0x20) as usize];
            for r in 0..16u64 {
                let row = g[r as usize] as u32;
                for c in 0..8u64 {
                    let a = (row >> (28 - 4 * c)) & 0xF;
                    if a != 0 && !self.put(f, x0 + c, y0 + r, mix(fg, bg, a)) {
                        return;
                    }
                }
            }
        } else if let Ok(i) = WIDE_UI_CP.binary_search(&k) {
            // 宽字位图的墨迹底在 15 行，ASCII 的基线在 10 行 ⇒ 宽字上移 5 行与英文**底部对齐**
            // （用户实测：面板里中文比英文高出一截）。
            let g = FONT_UI_WIDE[i];
            for r in 0..16u64 {
                let row = g[r as usize];
                for c in 0..16u64 {
                    let a = ((row >> (60 - 4 * c)) & 0xF) as u32;
                    if a != 0 && !self.put(f, x0 + c, y0 + r, mix(fg, bg, a)) {
                        return;
                    }
                }
            }
        }
    }

    /// `×` 形的两点笔画（标签页的关闭按钮、右侧的关闭按钮都用它）。
    fn cross(&self, f: &Frame, x0: u64, y0: u64, size: u64, color: u32) {
        for i in 0..size {
            for t in 0..2u64 {
                let _ = self.put(f, x0 + i, y0 + i + t, color);
                let _ = self.put(f, x0 + size - 1 - i, y0 + i + t, color);
            }
        }
    }

    /// 标签栏。`n_tabs` 是要显示的标签数：**装不下时**最右端画一个 `»`（折叠成下拉，
    /// 与 Windows Terminal 同形）。今天只有 1 个会话 ⇒ 那个分支走不到，规则先按布局写好。
    /// 画**一个标签**（悬停/活动底色、图标、标题、×/圆点）。整条重画会让顶部闪一下，
    /// 悬停变化时只重画受影响的那两个。
    fn draw_tab_abs(&self, f: &Frame, lay: &BarLayout, i: u64, active: u64,
                    hover: Option<u8>, unread: u64) {
        let c0 = lay.tab_col(i);
        let x0 = c0 * CELL_W;
        let tab_w = lay.tab_w;
        let wtab = tab_w * CELL_W;
        // 参考图里标签**不顶到条顶**：条 40px、标签 32px、上面留 8px。
        // 我们是 32px 的条，所以留 4px，标签 28px。圆角只做**顶部**——底部要与正文
        // 连成一片（参考图里活动页底边没有缝，四角全圆会画出一条条底色）。
        const TAB_TOP: u64 = 8; // 参考图：条 40、标签 32，上留 8
        let tab_h = BAR_H - TAB_TOP;
        // S9i：每个标签**自己刷自己的底**（活动=正文色 / 悬停=悬停色 / 其余=条底）。
        // tab_bar 不再整条先刷底，标签状态变化（活动↔非活动）靠这里自刷覆盖，
        // 单缓冲下就不会出现"整条空白"的中间帧（加标签闪烁的真因）。
        let tbg = if i == active {
            BG
        } else if hover == Some(i as u8) {
            TAB_HOVER_BG
        } else {
            TITLE_BG
        };
        self.rounded_top_abs(f, x0, TAB_TOP, wtab, tab_h, tbg, TITLE_BG);
        // `>_` 图标（几何画，不依赖字体里有没有这两个字形）。**每个标签都画**——
        // 只有活动页画的话，非活动页的文字会空出图标那两格、看着像缩进错位。
        // 图标：参考图 16×16、距标签左缘 10px、垂直居中。
        let icon = if i == active { TAB_ICON } else { TAB_ICON_DIM };
        for k in 0..7u64 {
            let _ = self.put_abs(f, x0 + 10 + k, 17 + k, icon);
            let _ = self.put_abs(f, x0 + 10 + k, 29 - k, icon);
        }
        self.rect_abs(f, x0 + 18, 30, 8, 2, icon);
        // 图标占前两格，标题从第三格起（图标与标题之间留一格，参考图也是这个呼吸感）
        let mut c = c0 + 3;
        // 0 号标签叫 "Aurora shell"，其余叫 "shell N"
        let mut label = [0u8; 24];
        let mut n = 0usize;
        if i == 0 {
            for ch in TAB_LABEL.chars() {
                if n < label.len() {
                    label[n] = ch as u8;
                    n += 1;
                }
            }
        } else {
            for ch in "shell ".chars() {
                if n < label.len() {
                    label[n] = ch as u8;
                    n += 1;
                }
            }
            if n < label.len() && i < 10 {
                label[n] = b'0' + i as u8;
                n += 1;
            }
        }
        // 标签文字用**界面字号**（半号 8×16），正文仍是 2×；参考图的标签文字就比正文小。
        // 推进按像素（ASCII 8、宽字 16），否则半号字形配整格推进会变成"字距拉满"。
        let ink = if i == active { TAB_INK } else { TAB_INK_DIM };
        if let Ok(lab) = core::str::from_utf8(&label[..n]) {
            // 底色跟着标签走（活动页是正文色，非活动/悬停是条底/悬停底）。
            let bg = if i == active {
                BG
            } else if hover == Some(i as u8) {
                TAB_HOVER_BG
            } else {
                TITLE_BG
            };
            let mut cx = x0 + 38; // 10 内边距 + 16 图标 + 12 间隙（参考图同款）
            for ch in lab.chars() {
                self.ch_ink_ui_abs(f, cx, 19, ch, ink, bg);
                cx += if (ch as u32) < 0x80 { 8 } else { 16 };
            }
        }
        let _ = c;
        // #58：条目右上角**只有 `×`**，且只在"活动标签"或"指针停在它上面"时画；
        // 非活动且没悬停时，若这个会话有新输出就画一个**未读圆点**（同样占那一格）。
        let x_visible = i as u64 == active || hover == Some(i as u8);
        // 关闭 `×` 的右边距与图标左边距一致（都是 10 px）⇒ `×` 右缘落在 tab_end-10。
        let xr = (c0 + tab_w) * CELL_W - 19;
        if x_visible {
            // 参考图里 `×` 不是贴右边缘：右边还留 ~24px。
            let ink = if i == active { TAB_INK } else { TAB_INK_DIM };
            self.cross_abs(f, xr, 19, 9, ink);
        } else if unread & (1u64 << i) != 0 {
            // 圆点：6×6 切掉四角（位图里画不出真圆，切角是最接近的形状）。
            self.rect_abs(f, xr + 2, 21, 4, 6, TAB_TEXT);
            self.rect_abs(f, xr + 1, 22, 6, 4, TAB_TEXT);
        }

    }

    /// 悬停变化：**只重画离开和进入的那两个标签**（整条重画会让顶部闪一下）。
    pub fn bar_hover(&self, f: &Frame, n_tabs: u64, active: u64,
                     old: Option<u8>, new: Option<u8>, unread: u64) {
        let lay = BarLayout::of(self.cols);
        let shown = n_tabs.min(lay.fit);
        const TAB_TOP: u64 = 8;
        // 离开的那个：整块刷回条底（它不再有 hover 底，必须清）。
        // **哪怕这个标签已经被关掉**也要清——旧悬停底留在那里，看起来就像标签还在
        // （实测：关掉 1 号标签后，它那块 `#3A3A3A` 一直留着）。
        if let Some(o) = old {
            let x0 = lay.tab_col(o as u64) * CELL_W;
            self.rect_abs(f, x0, TAB_TOP, lay.tab_w * CELL_W, BAR_H - TAB_TOP, TITLE_BG);
            if (o as u64) < shown {
                self.draw_tab_abs(f, &lay, o as u64, active, new, unread);
            }
        }
        // 进入的那个：它的 hover 底会整块盖住，**不再先刷**——先刷一遍再画就是"闪一下"。
        if let Some(n) = new {
            if Some(n) != old && (n as u64) < shown {
                self.draw_tab_abs(f, &lay, n as u64, active, new, unread);
            }
        }
        // 抹掉的那块矩形从 `plus_col` 那一列开始 ⇒ `+`/`∨` 跟着没了；hover 重画不经过
        // 整条 `tab_bar`，所以在这里补回来（关掉最后一个标签后，条上至少还剩两枚可点的图标）。
        self.plus_chevron(f, &lay, shown);
    }

    /// `+` 与它右边那个 `∨`。**单独成一个方法**：`tab_col(i)` 恰好等于 `plus_col(i)`，
    /// 所以 `bar_hover` 抹掉一个标签的那块 240px **正好把这两枚图标一起抹掉**；而 hover
    /// 重画不经过整条 `tab_bar` ⇒ 之前没人把它们画回来（实测：40px 的条上一个墨点都没有）。
    fn plus_chevron(&self, f: &Frame, lay: &BarLayout, shown: u64) {
        if lay.fit == 0 {
            return;
        }
        let plus_c = lay.plus_col(shown);
        if plus_c + 1 >= lay.strip_r {
            return;
        }
        // 两枚图标相互间隔 10 px、垂直中心 24（与标签里 `×` 同一条线）。
        let base = plus_c * CELL_W;
        let px0 = base + 10;
        self.rect_abs(f, px0 + 5, 18, 2, 12, TAB_TEXT);
        self.rect_abs(f, px0, 23, 12, 2, TAB_TEXT);
        self.rect_abs(f, base + 32, 16, 1, 16, MENU_EDGE);
        let dx = base + 43;
        for k in 0..6u64 {
            self.rect_abs(f, dx + k, 21 + k, 2, 1, TAB_DIM);
            self.rect_abs(f, dx + 11 - k, 21 + k, 2, 1, TAB_DIM);
            self.rect_abs(f, dx + k, 22 + k, 2, 1, TAB_DIM);
            self.rect_abs(f, dx + 11 - k, 22 + k, 2, 1, TAB_DIM);
        }
    }

    pub fn tab_bar(&self, f: &Frame, n_tabs: u64, active: u64, hover: Option<u8>, unread: u64) {
        let w = self.cols * CELL_W;
        // 2) 标签：几何来自 `BarLayout`（与命中测试同一份）
        let lay = BarLayout::of(self.cols);
        let (tab_w, strip_r, fit) = (lay.tab_w, lay.strip_r, lay.fit);
        let shown = n_tabs.min(fit);
        // 1) S9i：只清"左缘 + 末标签以右"两条带；标签矩形由 draw_tab_abs 自刷底。
        //    旧版先整条刷 TITLE_BG 再画标签，单缓冲下显示器会抓到"整条空白"的中间帧
        //    ⇒ 加/减标签时整条闪一下。现在标签区从不被整体刷白，闪烁消除。
        let left_end = lay.strip_l * CELL_W;
        self.rect_abs(f, 0, 0, left_end, BAR_H, TITLE_BG);
        // 顶缘（标签圆角以上 8px）恒为条底：不整条刷白后这里若不清，会留下上一帧的黑块
        // （用户实测"多出来一块黑色"）。只刷这 8px 薄带，标签区仍由 draw_tab_abs 自刷。
        self.rect_abs(f, 0, 0, w, 8, TITLE_BG);
        let tail_x = lay.tab_col(shown) * CELL_W;
        if tail_x < w {
            self.rect_abs(f, tail_x, 0, w - tail_x, BAR_H, TITLE_BG);
        }

        for i in 0..shown {
            self.draw_tab_abs(f, &lay, i, active, hover, unread);
        }
        // 3) `+` 与它右边那个 `∨`：单独成方法，因为 `bar_hover` 也必须能补画它们。
        self.plus_chevron(f, &lay, shown);
        // 4) 装不下 ⇒ 折叠指示（今天到不了）
        if n_tabs > fit {
            let x = strip_r.saturating_sub(1) * CELL_W + 4;
            for i in 0..5u64 {
                let _ = self.put_abs(f, x + 3 + i, 12 + i, TAB_TEXT);
                let _ = self.put_abs(f, x + 7 - i, 12 + i, TAB_TEXT);
            }
        }
        // 5) 右侧三个窗口按钮（绘制在 `win_buttons` 里，最大化时也用它）
        self.win_buttons(f, strip_r);
    }

    /// 只重画面板的**一行**（悬停在一行之间移动时用；整块重画会让列表闪一下）。
    pub fn menu_row(&self, f: &Frame, tabs: u64, rows: &[MenuRow], i: u8, hover: Option<u8>) {
        let (x, y, n) = menu_rect(self.cols, tabs, rows.len() as u64);
        if i >= n as u8 {
            return;
        }
        let yy = y + MENU_PAD_T + i as u64 * MENU_ROW_H;
        self.rect_abs(f, x * CELL_W + MENU_PAD_X - 1, yy, MENU_W * CELL_W - 2 * MENU_PAD_X + 2,
                      MENU_ROW_H, MENU_BG);
        let r = &rows[i as usize];
        let mbg = if hover == Some(i) {
            self.rounded_rect_abs(
                f,
                x * CELL_W + MENU_PAD_X,
                yy + 1,
                MENU_W * CELL_W - 2 * MENU_PAD_X,
                MENU_ROW_H - 2,
                MENU_BG_HOVER,
                MENU_BG,
                4,
            );
            MENU_BG_HOVER
        } else {
            MENU_BG
        };
        let ink = if r.dim { TAB_DIM } else { TAB_INK };
        let mut c = x + 2 + MENU_PAD_X / CELL_W;
        for ch in r.label.chars() {
            self.ch_ink_ui_abs(f, c * CELL_W, yy + 8, ch, ink, mbg);
            c += char_cells(ch);
        }
        let hl = cells_of(r.hint);
        let mut hc = (x + MENU_W).saturating_sub(2 + hl + MENU_PAD_X / CELL_W);
        for ch in r.hint.chars() {
            self.ch_ink_ui_abs(f, hc * CELL_W, yy + 8, ch, TAB_DIM, mbg);
            hc += char_cells(ch);
        }
    }

    /// #58：画 `∨` 下拉面板。**整块不透明**（面板下面就是正文），左边缘一道细线分开。
    pub fn menu_panel(&self, f: &Frame, tabs: u64, rows: &[MenuRow], hover: Option<u8>) {
        let (x, y, n) = menu_rect(self.cols, tabs, rows.len() as u64);
        // 面板本体：**没有左边框**（用户裁决），四角 8px 圆角，底部留 `MENU_PAD_B` 的空白。
        self.rounded_rect_abs(
            f,
            x * CELL_W,
            y,
            MENU_W * CELL_W,
            MENU_PAD_T + n * MENU_ROW_H + MENU_PAD_B,
            MENU_BG,
            BG,
            5,
        );
        for (i, r) in rows.iter().take(n as usize).enumerate() {
            let yy = y + MENU_PAD_T + i as u64 * MENU_ROW_H;
            if hover == Some(i as u8) {
                // hover 条自己也带圆角，且左右内缩 `MENU_PAD_X`（与面板边留出空隙）。
                self.rounded_rect_abs(
                    f,
                    x * CELL_W + MENU_PAD_X,
                    yy + 1,
                    MENU_W * CELL_W - 2 * MENU_PAD_X,
                    MENU_ROW_H - 2,
                    MENU_BG_HOVER,
                    MENU_BG,
                    4,
                );
            }
            let ink = if r.dim { TAB_DIM } else { TAB_INK };
            let mut c = x + 2 + MENU_PAD_X / CELL_W;
            let mbg = if hover == Some(i as u8) { MENU_BG_HOVER } else { MENU_BG };
            for ch in r.label.chars() {
                self.ch_ink_ui_abs(f, c * CELL_W, yy + 8, ch, ink, mbg);
                c += char_cells(ch);
            }
            let hl = cells_of(r.hint);
            let mut hc = (x + MENU_W).saturating_sub(2 + hl + MENU_PAD_X / CELL_W);
            for ch in r.hint.chars() {
                self.ch_ink_ui_abs(f, hc * CELL_W, yy + 8, ch, TAB_DIM, mbg);
                hc += char_cells(ch);
            }
        }
    }

    /// 三个窗口按钮：`-` / `□` / `×`，各占一格、笔画 10px 居中在 y=11..20。
    ///
    /// **绘制与命中共用 `BarLayout::strip_r`**：两处各算一遍，点击就会落在画的地方旁边。
    /// 最大化时标签栏不画，但这三个按钮仍画在右上角（`redraw_window` 会先清屏成底色）。
    fn win_buttons(&self, f: &Frame, strip_r: u64) {
        // #58 pass A：2 格宽 + 12 px 字形 + 2 px 笔画（`cross` 本来就是 2 px 粗）。
        let lay = BarLayout { strip_l: 1, strip_r, tab_w: 0, fit: 0 };
        let gx = |i: u64| lay.btn_col(i) * CELL_W + lay.glyph_x();
        let y0 = (BAR_H - GLYPH) / 2;
        let (w, t) = (GLYPH, 2u64);
        self.rect_abs(f, gx(0), y0 + GLYPH / 2 - 1, w, t, TAB_TEXT);
        self.rect_abs(f, gx(1), y0, w, t, TAB_TEXT);
        self.rect_abs(f, gx(1), y0 + GLYPH - t, w, t, TAB_TEXT);
        self.rect_abs(f, gx(1), y0, t, GLYPH, TAB_TEXT);
        self.rect_abs(f, gx(1) + w - t, y0, t, GLYPH, TAB_TEXT);
        self.cross_abs(f, gx(2), y0, GLYPH, TAB_TEXT);
    }

    /// 只画右上角那三个按钮（最大化：标签栏收起来了，按钮不能跟着消失）。
    pub fn buttons_only(&self, f: &Frame) {
        self.win_buttons(f, BarLayout::of(self.cols).strip_r);
    }

    /// 鼠标指针：7×11 的**几何箭头**（`#`=填充、`o`=描边），左上角是尖。
    /// 描边用正文底色，使它压在文字上也看得见；越界像素自动跳过。
    pub fn draw_pointer(&self, f: &Frame, x: i32, y: i32) {
        const ARROW: [&[u8]; 11] = [
            b"o......",
            b"oo.....",
            b"o#o....",
            b"o##o...",
            b"o###o..",
            b"o####o.",
            b"o#####o",
            b"o###ooo",
            b"o#o#o..",
            b"oo.o#o.",
            b"....o#o",
        ];
        for (r, row) in ARROW.iter().enumerate() {
            for (c, &px) in row.iter().enumerate() {
                let x0 = x + c as i32;
                let y0 = y + r as i32;
                if x0 < 0 || y0 < 0 {
                    continue;
                }
                let color = match px {
                    b'#' => FG,
                    b'o' => BG,
                    _ => continue,
                };
                if f.put(x0 as u64, y0 as u64, color).is_err() {
                    return;
                }
            }
        }
    }

    /// 整屏刷成背景色。终端模式开屏第一步：把启动阶段画的测试图案（S6a 的红绿蓝三条带）清掉。
    pub fn clear(&self, f: &Frame) {
        // 整屏（含标签条那一块）：绝对坐标，不随正文视口下移。
        let (w, h, _) = f.geom();
        for y in 0..h {
            for x in 0..w {
                if !self.put_abs(f, x, y, BG) {
                    return;
                }
            }
        }
    }

    /// 写一行文本（按字符宽度步进、末尾按格补空格）。返回占用的格数。
    pub fn print_line(&self, f: &Frame, row: u64, s: &str) -> usize {
        if Self::frozen() {
            return 0;
        }
        let mut col = 0u64;
        for ch in s.chars() {
            let w = char_cells(ch);
            if col + w > self.cols {
                break;
            }
            if !self.put_char(f, col, row, ch) {
                return 0;
            }
            col += w;
        }
        // 行尾补空格：不补的话上一行的残留像素会变成"下一行也画对了"的假证人
        while col < self.cols {
            if !self.put_char(f, col, row, ' ') {
                return 0;
            }
            col += 1;
        }
        col as usize
    }

    /// 只画一行里 `[c0, c1)` 这一段：先按格铺底、再落字。用于"面板收起后只铺回
    /// 被它盖住的那几列"，整行重画会让整段文字闪一下（用户实测）。
    pub fn print_span(&self, f: &Frame, row: u64, s: &str, c0: u64, c1: u64) {
        if Self::frozen() || row >= self.rows {
            return;
        }
        // **先铺底**（这一段里没有字的格也要铺，否则面板旧像素留着）
        let mut c = c0;
        while c < c1 && c < self.cols {
            self.rect(f, c * CELL_W, row * CELL_H, CELL_W, CELL_H, BG);
            c += 1;
        }
        let mut col = 0u64;
        for ch in s.chars() {
            let w = char_cells(ch);
            if col + w > c1 {
                break;
            }
            if col + w > c0 && col < c1 {
                if !self.put_char(f, col.min(self.cols.saturating_sub(1)), row, ch) {
                    return;
                }
            }
            col += w;
        }
    }

    /// 在正文区（`0 .. rows-BAND_ROWS`）画满确定性内容。返回画了多少行。
    ///
    /// **这里没有滚动**：滚动属于"真镜像日志"那一步（本片还没做），
    /// 现在正文是一次性写完的，所以不需要往上挪。
    pub fn fill_body(&self, f: &Frame) -> u64 {
        let body = self.rows - BAND_ROWS;
        for r in 0..body {
            let mut line = String::new();
            for c in 0..self.cols {
                // 内容由 (行, 列) 唯一决定 ⇒ 宿主机可以原样复算，不需要看内核的脸色
                line.push(char::from(b'A' + (((r * self.cols + c) % 26) as u8)));
            }
            self.print_line(f, r, &line);
        }
        body
    }

    /// 正文区整体上移**一个字符行**（只搬正文区，冻结带不参与）。
    ///
    /// 逐像素搬：`get` 拿原生打包值、`put_raw` 写回去，中间不做任何色彩转换。
    /// 不"只搬最后几行"糊弄——那会让"滚动了"这件事只有日志证人、没有像素证人。
    pub fn scroll_up(&self, f: &Frame) -> bool {
        if Self::frozen() {
            return false;
        }
        let top = 0u64;
        let bottom = (self.rows - BAND_ROWS) * CELL_H;   // 正文区底边（不含冻结带）
        for y in top..bottom - CELL_H {
            for x in 0..self.cols * CELL_W {
                match f.get(x, y + CELL_H) {
                    Ok(v) => { if f.put_raw(x, y, v).is_err() { return false; } }
                    Err(_) => return false,
                }
            }
        }
        // 腾出来的最后一行刷成背景，否则旧内容会在底部留一层"看起来像上一行"的残影
        for y in bottom - CELL_H..bottom {
            for x in 0..self.cols * CELL_W {
                if f.put_raw(x, y, BG).is_err() { return false; }
            }
        }
        true
    }

    /// 滚动一行，再把文本画在正文区最后一行。返回画出的字符格数。
    pub fn print_scrolled(&self, f: &Frame, s: &str) -> usize {
        if Self::frozen() {
            return 0;
        }
        if !self.scroll_up(f) {
            return 0;
        }
        self.print_line(f, self.rows - BAND_ROWS - 1, s)
    }

    /// 落冻结契约：把 [`BAND_TEXT`] 写进底部带，然后**永久闸门**关上。
    /// 返回 (带首行行号, 实际写出的格数)。调用方必须在串口上打一行"已冻结"给宿主机看。
    pub fn freeze_band(&self, f: &Frame) -> (u64, usize) {
        let top = self.rows - BAND_ROWS;
        // 先把带刷成纯背景，免得正文残留混进来让"命中"变成巧合
        for r in top..self.rows {
            self.print_line(f, r, "");
        }
        let mut wrote = 0usize;
        for (i, ch) in BAND_TEXT.chars().enumerate() {
            if i as u64 >= self.cols {
                break;
            }
            // 带还没冻结，所以 print 照常走；闸门在最后一步才关
            if self.put_char(f, i as u64, top, ch) {
                wrote += 1;
            }
        }
        FROZEN.store(true, Ordering::Release);
        (top, wrote)
    }

    /// 冻结带首行的像素左上角（宿主机按同一个数去 PPM 里取样）。
    pub fn band_origin(&self) -> (u64, u64) {
        (0, (self.rows - BAND_ROWS) * CELL_H)
    }
}

// ------------------------------------------------------------------ S6d 实时重画
//
/// **整窗重画**：把环里最后 `max_lines` 条完整行直接刷到正文区第 0.. 行，返回**有内容的行数**。
///
/// 与 [`drain_and_draw`] 的三点差别，每点都是"可重复调用"要求的：
/// 1. 不滚动，按行号直写 ⇒ 第 N 次调用与第 1 次调用画的是同一件事，宿主机可以任意时刻取样；
/// 2. **一个字都不打印**：每轮打一行会把 §245 那套按行序读的判据搅掉（而实时重画一轮都不打才成立）；
/// 3. 没画到的行也刷成空行：`print_line` 行尾补空格 ⇒ 上一帧更靠下的内容不会留下残影当假证人。
/// 返回 `(max_lines, 光标列, 光标行)`：光标**不再由这里画**（S6q）——
/// 它每 0.5 s 翻一次，而整窗重画一次是上百万次设备写；把闪烁画进重画里，
/// 每次眨眼都要重写整屏，画面上看到的就是"指针与文字一起闪"（实测 8 帧里丢 2 帧）。
/// 现在这里只画正文并把光标位置交回去，闪烁由 `LiveTerm` 在那一格上局部画/擦。
pub fn redraw_window(term: &Term, f: &Frame, max_lines: usize, sid: usize,
                     tabs: u64, active: u64, ch: Chrome,
                     hover: Option<u8>, unread: u64) -> (usize, u64, u64) {
    let n = crate::serial::mirror_len_sid(sid);
    let wrapped = crate::serial::mirror_wrapped_sid(sid);
    let mut total = 1usize;
    for i in 0..n {
        if crate::serial::mirror_byte_sid(sid, i) == 10 {
            total += 1;
        }
    }
    // 版面（S6t）：**标签栏（可收起）→ 正文自顶向下 → 尾行紧跟正文**。
    // 旧版把输入行钉在最后一行，是因为内核日志会一直往下写、提示符会被日志粘住；
    // 日志退出画面环之后那个理由没了，钉底反而让短会话的提示符悬在屏幕中间。
    // 写满才滚动：`skip = 总行数 - 可用行`。
    // 标签条已经画在正文视口之外（`BAR_H`）⇒ 正文永远从第 0 行起。
    let top = 0u64;
    let rows = max_lines.saturating_sub(top as usize);
    if ch.tabs() {
        term.clear_gap(f);
        term.tab_bar(f, tabs, active, hover, unread);
    } else {
        // 浮窗/最大化：先整块刷底色（否则上一帧的标签栏会留在第一行）。三个按钮**放到最后画**——
        // 正文从第 0 行开始，先画按钮会被第 0 行的文字整行盖掉（本轮实测：按钮像素 0）。
        for r in 0..max_lines as u64 {
            term.print_line(f, r, "");
        }
    }
    if !ch.body() {
        // 最小化：正文整块刷成底色，只留标签栏。输入行也不画（光标由调用方按 caret_at=None 收掉）。
        for r in top..max_lines as u64 {
            term.print_line(f, r, "");
        }
        return (max_lines, 0, 0);
    }
    let skip = total.saturating_sub(rows);
    let mut line = [0u8; LINE_BUF];
    let mut len = 0usize;
    let mut idx = 0usize;
    let mut row = 0usize;
    for i in 0..n {
        let c = crate::serial::mirror_byte_sid(sid, i);
        if c == 10 {
            let fragment = wrapped && idx == 0;
            if idx >= skip && !fragment && row < rows {
                // 合法 UTF-8 直接按字符画；被截断在多字节字符中间时取**合法前缀**
                // （`valid_up_to`）——只丢掉那半个字，而不是把整行的中文降级成 `?`
                // （用户截图里那串 `??????` 就是这么来的：200 字节上限切断了长中文行）。
                let r = top + row as u64;
                match core::str::from_utf8(&line[..len]) {
                    Ok(s) => term.print_line(f, r, s),
                    Err(e) => {
                        let ok = e.valid_up_to();
                        term.print_line(f, r, core::str::from_utf8(&line[..ok]).unwrap_or(""))
                    }
                };
                // 每一行**计入的行**都占一行（`print_line` 对非空串至少画一格，空串也要占，
                // 否则就没有"空行"了）。尾行定位与 [`redraw_input`] 用同一个口径，
                // 两边不一致的表现不是报错，是每敲一个键提示符跳一行。
                row += 1;
            }
            len = 0;
            idx += 1;
        } else if c == 0x08 || c == 0x7F {
            // 退格：shell 擦一个字符写的是 "\b \b"（退格、空格、退格）。
            // 在**行缓冲**这一层实现"删掉上一个字符"才是对的 —— 把控制字节画成 '?'
            // 会得到 "??"，看起来像退格键把字打坏了（用户实测反馈）。
            while len > 0 {
                len -= 1;
                if line[len] & 0xC0 != 0x80 {
                    break; // 退到 UTF-8 首字节（一个汉字 3 字节，不能只退一个）
                }
            }
        } else if len < line.len() {
            line[len] = c;
            len += 1;
        }
    }
    // **尾行 = 没有换行结尾的那一段**（提示符 + 正在键入），它紧跟在正文最后一行后面；
    // 正文写满 `rows` 行时它占最后一行（这就是滚动）。
    let mut caret = (0u64, 0u64);
    if rows > 0 {
        let tail_row = row.min(rows - 1);
        let (text, cc) = input_text(sid, &line[..len], term.cols);
        term.print_line(f, top + tail_row as u64, &text);
        // 尾行以下没被内容占满的行一律刷空：残影像素会被下一帧读成"那行还在"。
        let mut blank = tail_row + 1;
        while blank < rows {
            term.print_line(f, top + blank as u64, "");
            blank += 1;
        }
        caret = (cc, top + tail_row as u64);
    }
    // 最大化/浮窗时最后补上右上角三个按钮（压在第 0 行正文之上）。
    if !ch.tabs() && ch.buttons() {
        term.buttons_only(f);
    }
    (max_lines, caret.0, caret.1)
}
/// **只重画正文的若干行**（面板收起时用它把被盖住的行铺回来，不整窗重画）。
pub fn redraw_rows_range(term: &Term, f: &Frame, max_lines: usize, sid: usize,
                         r0: u64, r1: u64, c0: u64, c1: u64) {
    let n = crate::serial::mirror_len_sid(sid);
    let wrapped = crate::serial::mirror_wrapped_sid(sid);
    let mut total = 1usize;
    for i in 0..n {
        if crate::serial::mirror_byte_sid(sid, i) == 10 {
            total += 1;
        }
    }
    let rows = max_lines;
    // 内容没占到的行：只刷 `[c0,c1)` 这几列（整行刷会闪）。
    let mut r = r0;
    while r <= r1 && r < max_lines as u64 {
        term.print_span(f, r, "", c0, c1);
        r += 1;
    }
    let skip = total.saturating_sub(rows);
    let mut line = [0u8; LINE_BUF];
    let mut len = 0usize;
    let mut idx = 0usize;
    let mut row = 0usize;
    for i in 0..n {
        let c = crate::serial::mirror_byte_sid(sid, i);
        if c == 10 {
            let fragment = wrapped && idx == 0;
            if idx >= skip && !fragment && row < rows {
                if (row as u64) >= r0 && (row as u64) <= r1 {
                    match core::str::from_utf8(&line[..len]) {
                        Ok(t) => term.print_span(f, row as u64, t, c0, c1),
                        Err(e) => term.print_span(
                            f,
                            row as u64,
                            core::str::from_utf8(&line[..e.valid_up_to()]).unwrap_or(""),
                            c0,
                            c1,
                        ),
                    };
                }
                row += 1;
            }
            len = 0;
            idx += 1;
        } else if c == 0x08 || c == 0x7F {
            while len > 0 {
                len -= 1;
                if line[len] & 0xC0 != 0x80 {
                    break;
                }
            }
        } else if len < line.len() {
            line[len] = c;
            len += 1;
        }
    }
    // 尾行（未闭合的那段）
    if rows > 0 {
        let tail = row.min(rows - 1);
        if (tail as u64) >= r0 && (tail as u64) <= r1 {
            let (text, _) = input_text(sid, &line[..len], term.cols);
            term.print_span(f, tail as u64, &text, c0, c1);
        }
    }
}

/// 输入行的正文与光标列（S6q 抽出来，供整窗重画与**只重画输入行**两条路共用）。
///
/// S6t：影子半行那一档删掉了——环里现在只有会话自己写的字节，最后那一截未闭合的半行
/// 就是正在输入的那一行，不需要第二个来源。
fn input_text(_sid: usize, tail: &[u8], cols: u64) -> (alloc::string::String, u64) {
    let mut text: alloc::string::String = alloc::string::String::new();
    if !tail.is_empty() {
        text.push_str(match core::str::from_utf8(tail) {
            Ok(t) => t,
            Err(e) => core::str::from_utf8(&tail[..e.valid_up_to()]).unwrap_or(""),
        });
    }
    let cc = cells_of(&text).min(cols.saturating_sub(1));
    (text, cc)
}

/// **只重画输入行**（S6q）：换行数没变 ⇒ 正文区一个字都没动，变的只有尾部那半行。
///
/// 为什么值得单开一条路：整窗重画是 23 行 × 80 格 × 512 像素 ≈ 94 万次 UC 设备写，
/// 每敲一个键就做一次的话，那几十毫秒里指针/光标是被擦掉的（实测 8 帧里能抓到丢帧）。
/// 返回 `(光标列, 行)`。
pub fn redraw_input(term: &Term, f: &Frame, max_lines: usize, sid: usize, ch: Chrome) -> (u64, u64) {
    // 标签条已经画在正文视口之外（`BAR_H`）⇒ 正文永远从第 0 行起。
    let top = 0u64;
    let rows = max_lines.saturating_sub(top as usize);
    if rows == 0 {
        return (0, 0);
    }
    let n = crate::serial::mirror_len_sid(sid);
    let mut line = [0u8; LINE_BUF];
    let mut len = 0usize;
    let mut nl = 0usize;
    for i in 0..n {
        let c = crate::serial::mirror_byte_sid(sid, i);
        if c == 10 {
            len = 0;
            nl += 1;
        } else if c == 0x08 || c == 0x7F {
            while len > 0 {
                len -= 1;
                if line[len] & 0xC0 != 0x80 {
                    break;
                }
            }
        } else if len < line.len() {
            line[len] = c;
            len += 1;
        }
    }
    // **尾行必须与整窗路径算到同一行**（S6t）：整窗那边是"逐行画、`row` 自增"，
    // 这里是同一式的闭式解——`skip` 之上的完整行数，扣掉环绕后那段残行，再夹到 `rows`。
    // 两边不一致的表现不是报错，是每敲一个键提示符跳一行。
    let skip = (nl + 1).saturating_sub(rows);
    let mut shown = nl.saturating_sub(skip);
    if crate::serial::mirror_wrapped_sid(sid) && skip == 0 && shown > 0 {
        shown -= 1;
    }
    let in_row = top + shown.min(rows - 1) as u64;
    let (text, cc) = input_text(sid, &line[..len], term.cols);
    term.print_line(f, in_row, &text);
    (cc, in_row)
}

// ------------------------------------------------------------------ S6b-3 消费端
//
/// 把会话输出环里**最后 `max_lines` 行**逐行滚动画上去，返回 `(窗口行数, 真画上去的行数)`。
///
/// **环住在 `serial`，这里只读** ⇒ 边保持 `display -> diagnostics` 单向，不造新环（§244）。
/// **不许开 `Vec`**：堆上限 `LARGE_MAX = 2048`，一次 8 KiB 的 `with_capacity` 第一下就走
/// `handle_alloc_error` ⇒ 整机 39（ADR-018/026）。所以两遍扫描 + 栈上 200 字节行缓冲，
/// 装满就截断——宁可少画几个字符也要有界。
pub fn drain_and_draw(term: &Term, f: &Frame, max_lines: usize) -> (usize, usize) {
    let n = crate::serial::mirror_len();
    let wrapped = crate::serial::mirror_wrapped();
    // 第一遍：只数换行，不分配、不画图
    let mut total = 1usize;
    for i in 0..n {
        if crate::serial::mirror_byte(i) == 10 {
            total += 1;
        }
    }
    let skip = total.saturating_sub(max_lines);
    let mut line = [0u8; LINE_BUF];
    let mut len = 0usize;
    let mut idx = 0usize;
    let mut drawn = 0usize;
    for i in 0..n {
        let c = crate::serial::mirror_byte(i);
        if c == 10 {
            // 绕回处那一段是上一行的残片，不是完整的一行：丢掉它，否则画面上是一条半截
            let fragment = wrapped && idx == 0;
            if idx >= skip && !fragment {
                // 合法 UTF-8 按字符滚动画上（宽字符占 2 格）；非法则逐字节兜底
                let drew = match core::str::from_utf8(&line[..len]) {
                    Ok(s) => term.print_scrolled(f, s),
                    Err(e) => {
                        let ok = e.valid_up_to();
                        term.print_scrolled(f, core::str::from_utf8(&line[..ok]).unwrap_or(""))
                    }
                };
                // 空行也占一次滚动，否则"画了 N 行"里的空行会谎报成内容行
                if drew > 0 || len == 0 {
                    drawn += 1;
                }
            }
            len = 0;
            idx += 1;
        } else if c == 0x08 || c == 0x7F {
            // 退格：shell 擦一个字符写的是 "\b \b"（退格、空格、退格）。
            // 在**行缓冲**这一层实现"删掉上一个字符"才是对的 —— 把控制字节画成 '?'
            // 会得到 "??"，看起来像退格键把字打坏了（用户实测反馈）。
            while len > 0 {
                len -= 1;
                if line[len] & 0xC0 != 0x80 {
                    break; // 退到 UTF-8 首字节（一个汉字 3 字节，不能只退一个）
                }
            }
        } else if len < line.len() {
            line[len] = c;
            len += 1;
        }
    }
    (total, drawn)
}

/// 一行最多缓存多少字节。最长一条日志正文实测 **604 字节**（含中文），取 640 留余量。
/// 原来是 200 —— 长中文行被截在半个字中间 ⇒ 整行降级成 `?`（§249 之后用户截图里那串 `??????`）。
const LINE_BUF: usize = 640;

